def is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    curr_val = 3
    while curr_val * curr_val <= num:
        if num % curr_val == 0:
            return False
        curr_val += 2
    return True

