def capitalize_sentences(txt):
    res = []
    curr_capitalize = True
    for idx, char in enumerate(txt):
        if curr_capitalize and 'a' <= char <= 'z':
            res.append(char.upper())
            curr_capitalize = False
        elif char in ('.', '!', '?'):
            res.append(char)
            curr_capitalize = True
        elif char == ' ' and curr_capitalize:
            res.append(char)
            # Stay curr_capitalize for the next non-space char
        else:
            res.append(char)
            curr_capitalize = False # If it's a non-space, non-punctuation char, stop capitalizing
    return "".join(res)

