def calculate_grade(curr_score: int) -> str:
    if not isinstance(curr_score, (int, float)):
        raise TypeError("Score must be a number.")
    if not (0 <= curr_score <= 100):
        raise ValueError("Score must be between 0 and 100.")

    # Using a list of tuples for grade thresholds
    cfg_grades = [(90, 'A'), (80, 'B'), (70, 'C'), (60, 'D')]

    for idx, (val_threshold, res_grade) in enumerate(cfg_grades):
        if curr_score >= val_threshold:
            return res_grade

    # If no grade found in the loop, it's an 'F'
    return 'F'

