def binary_to_decimal(bin_str):
    res = 0
    curr_pow = 1
    idx = len(bin_str) - 1
    while idx >= 0:
        char = bin_str[idx]
        if char == '1':
            res += curr_pow
        elif char != '0':
            raise ValueError("Invalid binary string")
        curr_pow *= 2
        idx -= 1
    return res

