def decimal_to_binary(decimal_int):
    if decimal_int == 0:
        return '0'

    res = []
    curr_val = decimal_int

    while curr_val > 0:
        rem_val = curr_val % 2
        res.append(str(rem_val))
        curr_val //= 2

    return "".join(res[::-1])

