def calculate_median(nums):
    nums.sort()
    num_elems = len(nums)
    if num_elems == 0:
        return None  # Or raise an error, depending on desired behavior for empty list

    idx_mid = num_elems // 2

    if num_elems % 2 == 1:
        res = nums[idx_mid]
    else:
        prev_val = nums[idx_mid - 1]
        curr_val = nums[idx_mid]
        res = (prev_val + curr_val) / 2.0

    return res

