def decrypt_caesar(text, shift):
    res_chars = []
    alphabet_size = 26
    for curr_char in text:
        if 'a' <= curr_char <= 'z':
            curr_pos = ord(curr_char) - ord('a')
            prev_pos = (curr_pos - shift + alphabet_size) % alphabet_size
            decrypted_char = chr(prev_pos + ord('a'))
            res_chars.append(decrypted_char)
        else:
            res_chars.append(curr_char)
    res_msg = "".join(res_chars)
    return res_msg

