def harmonic_mean(numbers: list[float]) -> float:
    if not numbers:
        return 0.0 # Or raise an error, depending on desired behavior for empty list

    res_sum_recip = 0.0
    cnt = 0
    for num in numbers:
        if num <= 0:
            raise ValueError("Input numbers must be positive.")
        res_sum_recip += 1 / num
        cnt += 1

    if cnt == 0:
        return 0.0 # Should be caught by the initial check, but for robustness

    mean_recip = res_sum_recip / cnt
    final_res = 1 / mean_recip
    return final_res

