def weighted_average(vals, wts):
    if not vals or not wts:
        return 0.0

    if len(vals) != len(wts):
        raise ValueError("Lengths of values and weights must be equal.")

    sum_prod = 0.0
    sum_wts = 0.0

    for idx in range(len(vals)):
        curr_val = vals[idx]
        curr_wt = wts[idx]
        sum_prod += curr_val * curr_wt
        sum_wts += curr_wt

    if sum_wts == 0:
        return 0.0

    res = sum_prod / sum_wts
    return res

