    sum_weights = 0.0

    for index in range(len(values)):
        current_value = values[index]
        current_weight = weights[index]
        sum_product += current_value * current_weight
        sum_weights += current_weight

    if sum_weights == 0:
        return 0.0

    result = sum_product / sum_weights
