def hex_to_decimal(hex_str: str) -> int:
    res = 0
    pow_val = 0
    for idx in range(len(hex_str) - 1, -1, -1):
        curr_char = hex_str[idx]
        val = 0
        if '0' <= curr_char <= '9':
            val = int(curr_char)
        elif 'A' <= curr_char <= 'F':
            val = ord(curr_char) - ord('A') + 10
        elif 'a' <= curr_char <= 'f':
            val = ord(curr_char) - ord('a') + 10
        else:
