def fibonacci_sequence(n: int) -> list[int]:
    if n <= 0:
        return []
    if n == 1:
        return [0]

    res = [0, 1]
    prev_val = 0
    curr_val = 1

    while True:
        next_val = prev_val + curr_val
        if next_val >= n:
            break
        res.append(next_val)
        prev_val = curr_val
        curr_val = next_val

    return res

