def encrypt_shift(text, shift):
    res = []
    alp_len = 26
    for curr_char in text:
        if 'a' <= curr_char <= 'z':
            start_ord = ord('a')
            idx = (ord(curr_char) - start_ord + shift) % alp_len
            res.append(chr(start_ord + idx))
        elif 'A' <= curr_char <= 'Z':
            start_ord = ord('A')
            idx = (ord(curr_char) - start_ord + shift) % alp_len
            res.append(chr(start_ord + idx))
        else:
            res.append(curr_char)
    final_res = "".join(res)
    return final_res

