def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    if len(strings) == 1:
        return strings[0]

    res = ""
    min_len = float('inf')
    for s_val in strings:
        min_len = min(min_len, len(s_val))

    for idx in range(min_len):
        char_at_idx = strings[0][idx]
        for s_curr in strings[1:]:
            if s_curr[idx] != char_at_idx:
                return res
        res += char_at_idx

    return res

