def is_valid_ipv4(ip_addr: str) -> bool:
    octets = ip_addr.split('.')
    if len(octets) != 4:
        return False

    for curr_octet_str in octets:
        if not curr_octet_str.isdigit():
            return False

        val = int(curr_octet_str)
        if not (0 <= val <= 255):
            return False

        # Additional check for leading zeros, e.g., '01'
        if len(curr_octet_str) > 1 and curr_octet_str.startswith('0'):
            return False

    return True

