def find_mode(numbers: list):
    """
    Finds the mode (most frequent element) in a list of numbers.
    If there are multiple modes, returns any one of them.
    """
    if not numbers:
        return None

    counts = {}
    for elem in numbers:
        counts[elem] = counts.get(elem, 0) + 1

    max_cnt = -1
    res = None
    for val, cnt in counts.items():
        if cnt > max_cnt:
            max_cnt = cnt
            res = val
    return res

