import math

def geometric_mean(nums: list[float | int]) -> float:
    if not nums:
        return 0.0

    prod_val = 1.0
    cnt_valid = 0
    for idx, num in enumerate(nums):
        if num <= 0:
            return 0.0
        prod_val *= float(num)
        cnt_valid += 1

    if cnt_valid == 0:
        return 0.0

    res = prod_val ** (1.0 / cnt_valid)
    return res

