def convert_base(num, b):
    if num == 0:
        return "0"

    digits = "0123456789ABCDEF"
    res = []
    curr_num = num

    while curr_num > 0:
        rem = curr_num % b
        res.append(digits[rem])
        curr_num //= b

    return "".join(res[::-1])

