def is_palindrome_string(s: str) -> bool:
    res = ""
    for char in s:
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9':
            res += char.lower()

    buf = len(res)
    if buf == 0:
        return True

    curr = 0
    prev = buf - 1
    while curr < prev:
        if res[curr] != res[prev]:
            return False
        curr += 1
        prev -= 1

    return True

