    if unit_from == 'C':
        tmp_c = val
    elif unit_from == 'F':
        tmp_c = (val - 32) * 5 / 9
    elif unit_from == 'K':
        tmp_c = val - 273.15

    res = 0.0
    if unit_to == 'C':
        res = tmp_c
    elif unit_to == 'F':
        res = (tmp_c * 9 / 5) + 32
    elif unit_to == 'K':
