import math

def is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    limit = int(math.sqrt(num))
    for idx in range(3, limit + 1, 2):
        if num % idx == 0:
            return False
    return True

